密码加密作为存储密码必须要进行加密操作保证数据的安全，一种常见的加密方式即MD5。
使用方法：
import org.springframework.util.DigestUtils;String password = &quot;123456&quot;;String md5Pwd = DigestUtils.md5DigestAsHex(password.getBytes());System.out.println(md5Pwd);


JWTJWT通常用于身份验证、信息交换。用户在登录后提交用户名和密码，后台生成JWT token返回前端。前端每次请求接口都在Header中携带token，后台验证token后放行。可以设置token有效期（如两小时），保证安全性。
使用方法：

导入JWT依赖
编写工具类
利用工具类生成 &#x2F; 解析JWT

  public class JwtUtil &#123;    // 安全密钥。在生产环境中，这个密钥必须很长、很复杂    // 使用 Keys.secretKeyFor 来生成一个安全的、足够强度的密钥。    private static final SecretKey SECRET_KEY = Keys.secretKeyFor(SignatureAlgorithm.HS256);    // 令牌过期时间（毫秒），这里设为1小时    private static final long EXPIRATION_TIME = 3600_000;    //生成 JWT 令牌    public static String generateToken(String username) &#123;        // 设置过期时间        Date now = new Date();        Date expiryDate = new Date(now.getTime() + EXPIRATION_TIME);        return Jwts.builder()                .setSubject(username) // 设置主题（主体内容）                .setIssuedAt(now)     // 设置签发时间                .setExpiration(expiryDate) // 设置过期时间                .signWith(SECRET_KEY) // 使用密钥签名                .compact();           // 压缩并生成最终的令牌字符串    &#125;    // 从令牌中解析出用户名（Subject）    public static String getUsernameFromToken(String token) &#123;        Claims claims = Jwts.parserBuilder()                .setSigningKey(SECRET_KEY) // 设置用于验证签名的密钥                .build()                .parseClaimsJws(token)    // 解析令牌，如果签名无效或过期会直接抛出异常                .getBody();               // 获取载荷（Claims）        return claims.getSubject(); // 返回主题（用户名）    &#125;    //     验证令牌是否有效（是否过期、签名是否正确）    public static boolean validateToken(String token) &#123;        try &#123;            Jwts.parserBuilder()                    .setSigningKey(SECRET_KEY)                    .build()                    .parseClaimsJws(token);            return true; // 如果没有抛出异常，说明令牌有效        &#125; catch (Exception e) &#123;            // 这里可以捕获各种异常，如：过期（ExpiredJwtException）、签名无效（SignatureException）等            System.out.println(&quot;令牌无效: &quot; + e.getMessage());            return false;        &#125;    &#125;&#125;


过滤器 Filter类似于大门保安，保证用户不会在未登录的情况下进入界面。过滤器会在请求到达服务器时拦截请求，从请求头解析JWT令牌并检查其有效性。
使用方法：
@WebFilter(urlPatterns = &quot;/*&quot;)public class LoginCheckFilter implements Filter &#123;    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)            throws IOException, ServletException &#123;        HttpServletRequest request = (HttpServletRequest) req;        String token = request.getHeader(&quot;token&quot;);        if (token == null) &#123;            System.out.println(&quot;未登录&quot;);            return;        &#125;        chain.doFilter(req, res);//放行    &#125;&#125;

在启动类上添加 @ServletComponentScan 以启用过滤器。

拦截器 Interceptor类似于检查权限的秘书，用于更细粒度的控制。拦截器可以检查角色权限或记录操作日志。
使用方法：
public class LoginInterceptor implements HandlerInterceptor &#123;    @Override    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) &#123;        String token = request.getHeader(&quot;token&quot;);        return token != null; // 有token放行    &#125;&#125;@Configurationpublic class WebConfig implements WebMvcConfigurer &#123;    @Override    public void addInterceptors(InterceptorRegistry registry) &#123;        registry.addInterceptor(new LoginInterceptor()).addPathPatterns(&quot;/**&quot;);    &#125;&#125;


AOP 面向切面编程AOP主要用于抽取项目中与核心逻辑无关但重复出现的代码，例如：

安全检查（进入环节前）
日志记录（方法执行前后）
事务管理（支付与发货要么都成功，要么都失败）
性能监控（统计耗时）

切面（Aspect）通过切点（Pointcut）在特定的连接点（Join Point）上执行通知（Advice）：
通知类型：

@Before：方法前执行
@After：方法后执行
@AfterReturning：成功执行后
@AfterThrowing：抛出异常后
@Around：环绕执行，可控制方法是否执行

使用方法：
//自定义注解，用于标识某个方法需要进行功能字段自动填充处理@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)public @interface AutoFill &#123;    //数据库操作类型：UPDATE INSERT    OperationType value();&#125;//自定义切面，实现公共字段自动填充处理逻辑@Aspect@Component@Slf4jpublic class AutoFillAspect &#123;    //切入点    @Pointcut(&quot;execution(* com.sky.mapper.*.*(..)) &amp;&amp; @annotation(com.sky.annotation.AutoFill)&quot;)     public void autoFillPointCut()&#123;&#125;    //前置通知，在通知中进行公共字段的赋值    @Before(&quot;autoFillPointCut()&quot;)    public void autoFill(JoinPoint joinPoint)&#123;        log.info(&quot;开始进行公共字段自动填充...&quot;);    &#125;    MethodSignature signature = (MethodSignature) joinPoint.getSignature();//通过连接点对象来获取签名，向下转型为MethodSignature    AutoFill autoFill = signature.getMethod().getAnnotation(AutoFill.class);//获得方法上的注解对象    OperationType operationType = autoFill.value();//获得数据库操作类型（Insert or Update）    Object[] args = joinPoint.getArgs(); //获得了方法所有的参数    if(args == null || args.length==0 )&#123; //没有参数        return;    &#125;    Object entity = args[0];//现在约定实体放在第1个位置,传入实体可能不同所以用Object    LocalDateTime now = LocalDateTime.now();Long currentId = BaseContext.getCurrentId();if(operationType == OperationType.INSERT)&#123;    //为4个公共字段赋值    try &#123;        Method setCreateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_CREATE_TIME, LocalDateTime.class); //把方法名全部换成常量类，防止写错        Method setCreateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_CREATE_USER, Long.class);        Method setUpdateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_TIME, LocalDateTime.class);        Method setUpdateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_USER, Long.class);        //4.根据当前不同的操作类型，为对应的属性通过反射来赋值        setCreateTime.invoke(entity,now);        setCreateUser.invoke(entity,currentId);        setUpdateTime.invoke(entity,now);        setUpdateUser.invoke(entity,currentId);    &#125;catch (Exception e)&#123;        e.printStackTrace();    &#125;    &#125;else if(operationType == OperationType.UPDATE)&#123;    try &#123;        //为2个公共字段赋值        Method setUpdateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_TIME, LocalDateTime.class);        Method setUpdateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_USER, Long.class);        //4.根据当前不同的操作类型，为对应的属性通过反射来赋值        setUpdateTime.invoke(entity, now);        setUpdateUser.invoke(entity, currentId);    &#125;catch (Exception e)&#123;        e.printStackTrace();    &#125;    &#125;    &#125;


HttpClient用于发送请求和接收响应的工具库，用于微服务间或第三方API（如支付、短信、地图等）调用。
使用案例：
import org.apache.http.client.methods.CloseableHttpResponse;import org.apache.http.client.methods.HttpGet;import org.apache.http.impl.client.CloseableHttpClient;import org.apache.http.impl.client.HttpClients;import org.apache.http.util.EntityUtils;CloseableHttpClient client = HttpClients.createDefault();//创建HttpClient对象HttpGet get = new HttpGet(&quot;https://api.example.com/data&quot;);//创建请求对象CloseableHttpResponse resp = client.execute(get);//发送请求，接受响应结果String result = EntityUtils.toString(resp.getEntity());//解析结果System.out.println(result);client.close();//关闭资源


事务处理 Transactional保证一组操作要么全部成功，要么全部失败。常用于数据库操作，确保一致性。
使用方法：
@Servicepublic class OrderService &#123;    @Transactional    public void createOrder() &#123;        saveOrder();        updateStock();    &#125;&#125;
若出现异常会自动回滚，可加上：@Transactional(rollbackFor = Exception.class)

WebSocketWebSocket是全双工通信，可以实现实时性和节省开销，非常适合用于实时聊天和在线协作等功能，重点在于实时更新。WebSocket 聊天系统包含：

建立连接
管理在线用户，即维护一个在线用户的列表，Key 可以是用户ID，Value 是对应的 WebSocket 会话对象
处理消息收发


私聊：服务器收到A的消息，解析出目标用户B，然后从在线用户列表中找到用户B的会话对象，通过该会话将消息发送出去。
群聊：服务器收到一条群聊消息，解析出目标群组，然后遍历该群组内所有在线用户的会话对象，依次将消息发送出去。


处理连接断开使用方法：添加依赖编写配置类WebSocketConfig编写 WebSocket处理类


#spring task是spring的任务调度工具，可以用于执行定时任务。比如下单系统中订单超时取消的任务，就适合用定时工具执行。使用方式：

引入依赖
启动类添加注解@EnableScheduling开启任务调度
定时任务类

public class OrderTask &#123;    @Autowired    private OrderMapper orderMapper;	//超过15分钟未支付的订单自动取消    @Scheduled(cron = &quot;0 * * * * ?&quot;)//每分钟触发一下    public void processTimeoutOrder() &#123;        log.info(&quot;定时处理超时订单:&#123;&#125;&quot;, LocalDateTime.now());        LocalDateTime time = LocalDateTime.now().plusMinutes(-15);        List&lt;Orders&gt; list = orderMapper.getByStatusAndOrderTimeLT(Orders.PENDING_PAYMENT, time);        if(list != null &amp;&amp; list.size() &gt; 0)&#123;            for (Orders orders : list) &#123;                orders.setStatus(Orders.CANCELLED);                orders.setCancelReason(&quot;支付超时&quot;);                orders.setCancelTime(LocalDateTime.now());                orderMapper.update(orders);            &#125;        &#125;    &#125;&#125;

Echarts和poiecharts是基于 Javascript 的数据可视化图表库，提供直观，生动，可交互，可个性化定制的数据可视化图表。示例代码
@RestController@RequestMapping(&quot;/admin/report&quot;)@Api(tags=&quot;数据统计相关接口&quot;)@Slf4jpublic class ReportController &#123;    @Autowired    private ReportService reportService;    //营业额统计    @GetMapping(&quot;/turnoverStatistics&quot;)    @ApiOperation(&quot;营业额统计&quot;)    public Result&lt;TurnoverReportVO&gt; turnoverStatistics(            @DateTimeFormat(pattern=&quot;yyyy-MM-dd&quot;) LocalDate begin,            @DateTimeFormat(pattern=&quot;yyyy-MM-dd&quot;) LocalDate end)&#123;        log.info(&quot;营业额数据统计：&#123;&#125;,&#123;&#125;&quot;,begin,end);        return Result.success(reportService.getTurnoverStatistics(begin,end));     &#125;&#125;@Service@Slf4jpublic class ReportServiceImpl implements ReportService &#123;    @Autowired    private OrderMapper orderMapper;    //统计指定时间区间内的营业额数据    public TurnoverReportVO getTurnoverStatistics(LocalDate begin,LocalDate end)&#123;        //当前集合用于存放从begin到end范围内的每天的日期        List&lt;LocalDate&gt; dateList = new ArrayList&lt;&gt;();        dateList.add(begin);        while(!begin.equals(end)) &#123;            //日期计算，计算指定日期的后一天对应的日期            begin = begin.plusDays(1);            dateList.add(begin);        &#125;        //存放每天的营业额        List&lt;Double&gt; turnoverList = new ArrayList&lt;&gt;();        for(LocalDate date : dateList)&#123;            //查询date日期对应的营业额数据，营业额是指：状态为“已完成”的订单金额合计。            //LocalDate只有年月日            LocalDateTime beginTime = LocalDateTime.of(date, LocalTime.MIN); //LocalTime.MIN相当于获得0点0分            LocalDateTime endTime = LocalDateTime.of(date,LocalTime.MAX);//无限接近于下一个日期的0点0分0秒            //select sum(amount) from orders where order_time &gt; ? and order_time &lt; ? and status = 5            //status==5代表订单已完成            Map map = new HashMap();            map.put(&quot;begin&quot;,beginTime);            map.put(&quot;end&quot;,endTime);            map.put(&quot;status&quot;, Orders.COMPLETED);            Double turnover = orderMapper.sumByMap(map); //算出当天的营业额            //考虑当天营业额为0的情况，会返回空            turnover = turnover == null ? 0.0:turnover;            turnoverList.add(turnover);        &#125;        //封装返回结果        return TurnoverReportVO                .builder()                .dateList(StringUtils.join(dateList,&quot;,&quot;))                .turnoverList(StringUtils.join(turnoverList,&quot;,&quot;))                .build();    &#125;&#125;
