编辑员工实行编辑操作前要开发完成查询操作，因为编辑时要查询之前的信息进行回显。编写代码与上述类似。
新增菜品public class DishServiceImpl implements DishService &#123;    //新增菜品对应的口味    @Transactional//保证事务一致性，需要在启动类上添加@EnableTransactionManagement注解    public void saveWithFlavor(DishDTO dishDTO) &#123;        Dish dish = new Dish();        BeanUtils.copyProperties(dishDTO,dish);        //想菜品表插入1条数据        dishMapper.insert(dish);        //获取insert语句生成的主键值        Long dishId = dish.getId();        //向口味表插入n条数据        List&lt;DishFlavor&gt; flavors = dishDTO.getFlavors();//获取要插入的口味        if(flavors != null &amp;&amp; flavors.size()&gt;0)&#123;            flavors.forEach(dishFlavor -&gt; &#123;                dishFlavor.setDishId(dishId);//获取菜的id插入flavors            &#125;);            //向口味表插入n条数据            dishFlavorMapper.insertBatch(flavors);        &#125;    &#125;&#125;&lt;mapper namespace=&quot;com.sky.mapper.DishFlavorMapper&quot;&gt;    &lt;insert id=&quot;insertBatch&quot;&gt;        insert into dish_flavor (dish_id,name,value) VALUES        &lt;foreach collection=&quot;flavors&quot; item=&quot;df&quot; separator=&quot;,&quot;&gt;            (#&#123;df.dishId&#125;,#&#123;df.name&#125;,#&#123;df.value&#125;)        &lt;/foreach&gt;    &lt;/insert&gt;&lt;/mapper&gt;
分页查询public PageResult pageQuery(DishPageQueryDTO dishPageQueryDTO)&#123;    PageHelper.startPage(dishPageQueryDTO.getPage(),dishPageQueryDTO.getPageSize());    Page&lt;DishVO&gt; page = dishMapper.pageQuery(dishPageQueryDTO);    return new PageResult(page.getTotal(),page.getResult());//直接在return封装PageResult&#125;前端请求的参数会被封装成DTO，因为categoryName是不存在菜品表里的，现在前端页面要展示分类名称，所以要定义VO，将VO转为JSON数据然后展示。

删除菜品删除操作要格外小心，要注意什么能删什么不能删
@Transactionalpublic void deleteBatch(List&lt;Long&gt; ids)&#123;    //不能删除：存在起售中的菜品    for (Long id : ids) &#123;        Dish dish = dishMapper.getById(id);        if(dish.getStatus()== StatusConstant.ENABLE)&#123; //状态为1起售中            //当前菜品处于起售中，不能删除            throw new DeletionNotAllowedException(MessageConstant.DISH_ON_SALE);        &#125;    &#125;    //不能删除：菜品被套餐关联    List&lt;Long&gt; setmealIds = setmealDishMapper.getSetmealIdsByDishIds(ids);    if(setmealIds != null &amp;&amp; setmealIds.size()&gt;0)&#123;        //当前菜品被套餐关联了，不能删除        throw new DeletionNotAllowedException(MessageConstant.DISH_BE_RELATED_BY_SETMEAL);    &#125;    //删除菜品表中的菜品数据    dishMapper.deleteByIds(ids);    //删除口味数据    dishFlavorMapper.deleteByDishIds(ids);&#125;//查看根据菜品id查询是否有对应的套餐id&lt;mapper namespace=&quot;com.sky.mapper.SetmealDishMapper&quot;&gt;    &lt;select id=&quot;getSetmealIdsByDishIds&quot; resultType=&quot;java.lang.Long&quot;&gt;        select setmeal_id from setmeal_dish where dish_id in        &lt;foreach collection=&quot;dishIds&quot; item=&quot;dishId&quot; separator=&quot;,&quot; open=&quot;(&quot; close=&quot;)&quot;&gt;            #&#123;dishId&#125;        &lt;/foreach&gt;    &lt;/select&gt;&lt;/mapper&gt;&lt;delete id=&quot;deleteByIds&quot;&gt;    delete from dish where id in    &lt;foreach collection=&quot;ids&quot; separator=&quot;,&quot; open=&quot;(&quot; close=&quot;)&quot;&gt;        #&#123;id&#125;    &lt;/foreach&gt;&lt;/delete&gt;

查询菜品（带缓存）短期大量查询数据库会导致压力过大，会卡顿，所以会将一些常用数据缓存到redis当中。
public class DishController &#123;    @Autowired    private DishService dishService;    @Autowired    private RedisTemplate redisTemplate;    // 根据分类id查询菜品    @GetMapping(&quot;/list&quot;)    @ApiOperation(&quot;根据分类id查询菜品&quot;)    public Result&lt;List&lt;DishVO&gt;&gt; list(Long categoryId) &#123;        //构造redis中的key，规则：dish_分类id        String key = &quot;dish_&quot; + categoryId;        //查询redis中是否存在菜品数据        List&lt;DishVO&gt; list = (List&lt;DishVO&gt;)redisTemplate.opsForValue().get(key);        if(list != null &amp;&amp; list.size()&gt;0)&#123;//如果存在，直接返回，无须查询数据库            return Result.success(list);        &#125;        Dish dish = new Dish();        dish.setCategoryId(categoryId);        dish.setStatus(StatusConstant.ENABLE);//查询起售中的菜品        //如果不存在，查询数据库，将查询到的数据放入redis中        list = dishService.listWithFlavor(dish);        redisTemplate.opsForValue().set(key,list);        return Result.success(list);    &#125;&#125;还要注意在更新或者删除菜品的时候，需要清理缓存，否则数据就不同步了//清理缓存数据private void cleanCache(String pattern)&#123;    Set keys = redisTemplate.keys(pattern);    redisTemplate.delete(keys);&#125;String key = &quot;dish_&quot; + dishDTO.getCategoryId();cleanCache(key);//清理缓存数据

spring cache注解SpringCache是Spring提供的缓存框架。提供了基于注解的缓存功能。使用方式：

引入依赖
在启动类加上注解@EnableCaching
在相应的controller方法上加上注解例如：@Cacheable(cacheNames&#x3D;”setmealCache”,key&#x3D;”#categoryId”)@CacheEvict(cacheNames &#x3D; “setmealCache”,allEntries &#x3D; true)@CachePut(cacheNames&#x3D;”userCache”,key&#x3D;”#a0.id”)

添加购物车（逻辑较为复杂）@Service@Slf4jpublic class ShoppingCartServiceImpl implements ShoppingCartService &#123;    @Autowired    private ShoppingCartMapper shoppingCartMapper;    @Autowired    private DishMapper dishMapper;    @Autowired    private SetmealMapper setmealMapper;    @Override    public void addShoppingCart(ShoppingCartDTO shoppingCartDTO) &#123;        //判断当前加入购物车中的商品是否已经存在了        ShoppingCart shoppingCart = new ShoppingCart();        BeanUtils.copyProperties(shoppingCartDTO,shoppingCart);        //userid暂时还不知道，从ThreadLocal取        Long userId = BaseContext.getCurrentId();        shoppingCart.setUserId(userId);        List&lt;ShoppingCart&gt; list = shoppingCartMapper.list(shoppingCart);        //如果已经存在，只需要数量+1        if(list != null &amp;&amp; list.size()&gt;0) &#123;            ShoppingCart cart = list.get(0);            cart.setNumber(cart.getNumber()+1);            shoppingCartMapper.updateNumberById(cart);        &#125;else &#123;//如果不存在，则需要插入一条购物车数据            //判断本次添加到购物车的是菜品还是套餐,因为要查询不同表            Long dishId = shoppingCartDTO.getDishId();            if(dishId!=null)&#123;                //本次添加到购物车的是菜品                Dish dish = dishMapper.getById(dishId);                shoppingCart.setName(dish.getName());                shoppingCart.setImage(dish.getImage());                shoppingCart.setAmount(dish.getPrice());            &#125;else&#123;                //本次添加到购物车的是套餐                Long setmealId = shoppingCartDTO.getSetmealId();                Setmeal setmeal = setmealMapper.getById(setmealId);                shoppingCart.setName(setmeal.getName());                shoppingCart.setImage(setmeal.getImage());                shoppingCart.setAmount(setmeal.getPrice());            &#125;            shoppingCart.setNumber(1);            shoppingCart.setCreateTime(LocalDateTime.now());            shoppingCartMapper.insert(shoppingCart);        &#125;    &#125;&#125;

用户下单（捋顺逻辑链）@Servicepublic class OrderServiceImpl implements OrderService &#123;    @Autowired    private OrderMapper orderMapper;    @Autowired    private OrderDetailMapper orderDetailMapper;    @Autowired    private AddressBookMapper addressBookMapper;    @Autowired    private ShoppingCartMapper shoppingCartMapper;    @Transactional    public OrderSubmitVO submitOrder(OrdersSubmitDTO orderSubmitDTO)&#123;        //1.处理各种业务异常（地址簿为空，购物车数据为空）        //地址簿为空        AddressBook addressBook = addressBookMapper.getById(orderSubmitDTO.getAddressBookId());        if(addressBook == null)&#123;            //抛出业务异常            throw new AddressBookBusinessException(MessageConstant.ADDRESS_BOOK_IS_NULL);        &#125;        //查询当前用户的购物车数据        Long userId = BaseContext.getCurrentId();        ShoppingCart shoppingCart = new ShoppingCart();        shoppingCart.setUserId(userId);        List&lt;ShoppingCart&gt; shoppingCartList = shoppingCartMapper.list(shoppingCart);        if(shoppingCartList == null || shoppingCartList.size()==0)&#123;            throw new ShoppingCartBusinessException(MessageConstant.ADDRESS_BOOK_IS_NULL);        &#125;        //2.向订单表插入1条数据        Orders orders = new Orders();        BeanUtils.copyProperties(orderSubmitDTO,orders);        orders.setOrderTime(LocalDateTime.now());        orders.setPayStatus(Orders.UN_PAID);        orders.setStatus(Orders.PENDING_PAYMENT);        orders.setNumber(String.valueOf(System.currentTimeMillis()));        orders.setPhone(addressBook.getPhone());        orders.setConsignee(addressBook.getConsignee());        orders.setUserId(userId);        orderMapper.insert(orders);        List&lt;OrderDetail&gt; orderDetailList = new ArrayList&lt;&gt;();        //3.向订单明细表插入n条数据        for(ShoppingCart cart: shoppingCartList)&#123;            OrderDetail orderDetail = new OrderDetail();//订单明细            BeanUtils.copyProperties(cart,orderDetail);            orderDetail.setOrderId(orders.getId());//设置当前订单明细关联的订单id            orderDetailList.add(orderDetail);        &#125;        orderDetailMapper.insertBatch(orderDetailList);        //4.清空当前用户的购物车数据        shoppingCartMapper.deleteByUserId(userId);        //5.封装VO返回结果        OrderSubmitVO orderSubmitVO = OrderSubmitVO.builder()                .id(orders.getId())                .orderTime(orders.getOrderTime())                .orderAmount(orders.getAmount())                .build();        return orderSubmitVO;    &#125;&#125;

小结大二学的很痛苦，实际上最重要的还是搞清楚业务的逻辑链，不要出纰漏，但是对于那个时候的我没把这些东西想明白。而且学的时候，觉得总得搞清楚所有东西，恨不得细枝末节到注解源码都去理解清楚。但是对于不太聪明的我来说，看源码有点难度，而且还是初学者。有些东西是用熟的，没有必要无目的的刨根问底，人的精力和记忆力也没那么强大。了解了这一点之后觉得学习技术豁然开朗，用一句话总结就是先完成再完美嘛。其实总结下来也就只用了短短三天去阅读和编写，比起当时一头雾水的学，效果好很多。大二到大三这短短几个月其实心态和思想变了很多，越学还是越觉得学海无涯，仍需努力。

最近闲着没事，想着把几个常用的 AI 能力集成到应用中。选了三个比较有代表性的：TTS（文字转语音）、OCR（图片文字识别）、LLM（大语言模型）。
用 Spring Boot 当后端框架，把这三个能力封装成接口，方便以后复用。

一、这三个东西到底是啥TTS（Text-to-Speech）文字转语音，就是你给一段文字，它给你返回一段音频。常见场景：语音播报、有声读物、智能客服。
OCR（Optical Character Recognition）图片文字识别，你传一张图，它把图里的文字提取出来。常见场景：身份证识别、发票录入、截图转文字。
以上两个用的都是腾讯的api
LLM（Large Language Model）大语言模型，就是你问它问题，它给你回答。这个调用方式有很多种，java也有langchain4j专门调用LLM，上篇博客有说到，本次简单带过一下

二、整体思路我的设计很简单：

写三个独立的 Service，分别封装 TTS、OCR、LLM 的调用逻辑
写一个 Controller，暴露三个接口，分别测试
把配置文件抽到 application.yml 里，方便换 key

不搞复杂的业务串联，先保证每个功能都能跑通。

三、实战代码1.引入依赖&lt;dependencies&gt;    &lt;!-- Spring Boot Web --&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;        &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;    &lt;/dependency&gt;    &lt;!-- 腾讯云 SDK - 统一依赖，包含了 TTS 和 OCR --&gt;    &lt;dependency&gt;        &lt;groupId&gt;com.tencentcloudapi&lt;/groupId&gt;        &lt;artifactId&gt;tencentcloud-sdk-java&lt;/artifactId&gt;        &lt;version&gt;3.1.1309&lt;/version&gt;    &lt;/dependency&gt;    &lt;!-- JSON 解析 --&gt;    &lt;dependency&gt;        &lt;groupId&gt;com.alibaba&lt;/groupId&gt;        &lt;artifactId&gt;fastjson&lt;/artifactId&gt;        &lt;version&gt;2.0.32&lt;/version&gt;    &lt;/dependency&gt;&lt;/dependencies&gt;

2. 配置文件application.yml 长这样：
spring:  application:    name: demo# 腾讯云通用配置tencent:  cloud:    secret-id: &quot;SecretId&quot;    secret-key: &quot;SecretKey&quot;    # TTS 相关配置    tts:      endpoint: &quot;tts.tencentcloudapi.com&quot;      region: &quot;ap-guangzhou&quot;  # 地域      voice-type: 101001      # 音色ID，这部分在service层也可更换      codec: &quot;mp3&quot;            # 音频格式：mp3/wav/pcm      speed: 0                # 语速：-2到6，0是正常      volume: 0               # 音量：-10到10    # OCR 相关配置    ocr:      endpoint: &quot;ocr.tencentcloudapi.com&quot;      region: &quot;ap-guangzhou&quot;

3. TTS 服务@Service@Slf4jpublic class TtsService &#123;        @Value(&quot;$&#123;tencent.cloud.secret-id&#125;&quot;)    private String secretId;        @Value(&quot;$&#123;tencent.cloud.secret-key&#125;&quot;)    private String secretKey;        @Value(&quot;$&#123;tencent.cloud.tts.region&#125;&quot;)    private String region;        @Value(&quot;$&#123;tencent.cloud.tts.voice-type&#125;&quot;)    private Long voiceType;        @Value(&quot;$&#123;tencent.cloud.tts.codec&#125;&quot;)    private String codec;        @Value(&quot;$&#123;tencent.cloud.tts.speed&#125;&quot;)    private Float speed;        @Value(&quot;$&#123;tencent.cloud.tts.volume&#125;&quot;)    private Float volume;        private TtsClient client;        @PostConstruct    public void init() &#123;        // 实例化认证对象        Credential cred = new Credential(secretId, secretKey);                // 实例化 HTTP 配置        HttpProfile httpProfile = new HttpProfile();        httpProfile.setEndpoint(&quot;tts.tencentcloudapi.com&quot;);                // 实例化 Client 配置        ClientProfile clientProfile = new ClientProfile();        clientProfile.setHttpProfile(httpProfile);                // 实例化 TTS 客户端        this.client = new TtsClient(cred, region, clientProfile);    &#125;        public byte[] textToSpeech(String text) &#123;        try &#123;            // 构建请求            TextToSpeechRequest req = new TextToSpeechRequest();            req.setText(text);            req.setSessionId(UUID.randomUUID().toString());            req.setVoiceType(voiceType);            req.setCodec(codec);            req.setSpeed(speed);            req.setVolume(volume);                        // 调用 API            TextToSpeechResponse resp = client.TextToSpeech(req);                        // 返回的 Audio 是 Base64 编码的音频数据            String audioBase64 = resp.getAudio();            byte[] audioData = Base64.getDecoder().decode(audioBase64);                        log.info(&quot;TTS 转换成功，文本长度: &#123;&#125;, 音频大小: &#123;&#125; bytes&quot;,                 text.length(), audioData.length);            return audioData;                    &#125; catch (TencentCloudSDKException e) &#123;            log.error(&quot;TTS 调用失败: &#123;&#125;&quot;, e.getMessage());            return null;        &#125;    &#125;&#125;

4. OCR 服务@Service@Slf4jpublic class OcrService &#123;        @Value(&quot;$&#123;tencent.cloud.secret-id&#125;&quot;)    private String secretId;        @Value(&quot;$&#123;tencent.cloud.secret-key&#125;&quot;)    private String secretKey;        @Value(&quot;$&#123;tencent.cloud.ocr.region&#125;&quot;)    private String region;        private OcrClient client;        @PostConstruct    public void init() &#123;        Credential cred = new Credential(secretId, secretKey);                HttpProfile httpProfile = new HttpProfile();        httpProfile.setEndpoint(&quot;ocr.tencentcloudapi.com&quot;);                ClientProfile clientProfile = new ClientProfile();        clientProfile.setHttpProfile(httpProfile);                this.client = new OcrClient(cred, region, clientProfile);    &#125;        public String recognizeText(String imagePath) &#123;        try &#123;            // 读取图片并转为 Base64            File imageFile = new File(imagePath);            byte[] imageBytes = Files.readAllBytes(imageFile.toPath());            String imageBase64 = Base64.getEncoder().encodeToString(imageBytes);                        // 构建请求            GeneralBasicOCRRequest req = new GeneralBasicOCRRequest();            req.setImageBase64(imageBase64);                        // 调用 API            GeneralBasicOCRResponse resp = client.GeneralBasicOCR(req);                        // 解析结果            StringBuilder result = new StringBuilder();            for (TextDetection textDetection : resp.getTextDetections()) &#123;                result.append(textDetection.getDetectedText());            &#125;                        log.info(&quot;OCR 识别成功，识别文字长度: &#123;&#125;&quot;, result.length());            return result.toString();                    &#125; catch (Exception e) &#123;            log.error(&quot;OCR 识别失败: &#123;&#125;&quot;, e.getMessage());            return null;        &#125;    &#125;    public String recognizeTextFromUrl(String imageUrl) &#123;        try &#123;            GeneralBasicOCRRequest req = new GeneralBasicOCRRequest();            req.setImageUrl(imageUrl);                        GeneralBasicOCRResponse resp = client.GeneralBasicOCR(req);                        StringBuilder result = new StringBuilder();            for (TextDetection textDetection : resp.getTextDetections()) &#123;                result.append(textDetection.getDetectedText());            &#125;                        return result.toString();                    &#125; catch (TencentCloudSDKException e) &#123;            log.error(&quot;OCR 识别失败: &#123;&#125;&quot;, e.getMessage());            return null;        &#125;    &#125;&#125;

5. LLM 服务@Service@Slf4jpublic class LlmService &#123;        @Value(&quot;$&#123;openai.api-key&#125;&quot;)    private String apiKey;        @Value(&quot;$&#123;openai.model&#125;&quot;)    private String model;        private final OkHttpClient httpClient = new OkHttpClient();    public String chat(String prompt) &#123;        try &#123;            // 构建请求体            Map&lt;String, Object&gt; requestBody = new HashMap&lt;&gt;();            requestBody.put(&quot;model&quot;, model);                        List&lt;Map&lt;String, String&gt;&gt; messages = new ArrayList&lt;&gt;();            Map&lt;String, String&gt; userMessage = new HashMap&lt;&gt;();            userMessage.put(&quot;role&quot;, &quot;user&quot;);            userMessage.put(&quot;content&quot;, prompt);            messages.add(userMessage);            requestBody.put(&quot;messages&quot;, messages);                        String json = JSON.toJSONString(requestBody);                        // 构建 HTTP 请求            Request request = new Request.Builder()                .url(&quot;https://api.openai.com/v1/chat/completions&quot;)                .addHeader(&quot;Authorization&quot;, &quot;Bearer &quot; + apiKey)                .addHeader(&quot;Content-Type&quot;, &quot;application/json&quot;)                .post(RequestBody.create(json, MediaType.parse(&quot;application/json&quot;)))                .build();                        // 发送请求            Response response = httpClient.newCall(request).execute();            String responseBody = response.body().string();                        // 解析响应            JSONObject jsonResponse = JSON.parseObject(responseBody);            String reply = jsonResponse.getJSONArray(&quot;choices&quot;)                .getJSONObject(0)                .getJSONObject(&quot;message&quot;)                .getString(&quot;content&quot;);                        log.info(&quot;LLM 回复: &#123;&#125;&quot;, reply);            return reply;                    &#125; catch (Exception e) &#123;            log.error(&quot;LLM 调用失败&quot;, e);            return &quot;不好意思，出错了&quot;;        &#125;    &#125;&#125;

6. Controller 接口@RestController@RequestMapping(&quot;/api&quot;)@Slf4jpublic class AiController &#123;        @Autowired    private TtsService ttsService;        @Autowired    private OcrService ocrService;        @Autowired    private LlmService llmService;        @PostMapping(&quot;/tts&quot;)    public ResponseEntity&lt;byte[]&gt; tts(@RequestParam String text) &#123;        byte[] audio = ttsService.textToSpeech(text);        if (audio == null) &#123;            return ResponseEntity.status(500).build();        &#125;        return ResponseEntity.ok()            .contentType(MediaType.parseMediaType(&quot;audio/mpeg&quot;))            .body(audio);    &#125;        @PostMapping(&quot;/ocr&quot;)    public String ocr(@RequestParam String imagePath) &#123;        return ocrService.recognizeText(imagePath);    &#125;        @PostMapping(&quot;/ocr-url&quot;)    public String ocrFromUrl(@RequestParam String imageUrl) &#123;        return ocrService.recognizeTextFromUrl(imageUrl);    &#125;        @PostMapping(&quot;/chat&quot;)    public String chat(@RequestParam String prompt) &#123;        return llmService.chat(prompt);    &#125;&#125;


四、调优方法（踩坑经验）TTS 调优腾讯云的语速范围是 -2 到 6，负数变慢，正数变快：
// 慢速（适合讲故事、朗读）req.setSpeed(-1f);  // 0.8倍速req.setSpeed(-2f);  // 0.6倍速// 快速（适合新闻播报）req.setSpeed(1f);   // 1.2倍速req.setSpeed(2f);   // 1.5倍速

2. 选择合适的音色
情绪控制（仅部分音色支持）多情感音色可以设置情绪：
req.setEmotionCategory(&quot;happy&quot;);   // 高兴req.setEmotionCategory(&quot;sad&quot;);     // 悲伤req.setEmotionCategory(&quot;angry&quot;);   // 生气req.setEmotionCategory(&quot;fear&quot;);    // 恐惧req.setEmotionCategory(&quot;neutral&quot;); // 中性

3. 长文本分段处理
腾讯云 TTS 单次最多 150 个汉字（中文）或 500 个字母（英文）。超长文本需要分段
// 按句号分段String[] sentences = text.split(&quot;。&quot;);List&lt;byte[]&gt; audioParts = new ArrayList&lt;&gt;();for (String sentence : sentences) &#123;    if (!sentence.trim().isEmpty()) &#123;        byte[] part = textToSpeech(sentence + &quot;。&quot;);        audioParts.add(part);    &#125;&#125;

OCR 调优1. 使用高精度版接口
通用印刷体有普通版和高精度版，高精度版更准但略慢：
// 普通版 - GeneralBasicOCR// 高精度版 - GeneralAccurateOCRGeneralAccurateOCRRequest req = new GeneralAccurateOCRRequest();req.setImageBase64(imageBase64);GeneralAccurateOCRResponse resp = client.GeneralAccurateOCR(req);

2. 图片预处理
图片太暗、太糊都会影响识别。可以先用腾讯云的图像增强接口：
// 先用图像增强接口处理图片ImageEnhancementRequest enhanceReq = new ImageEnhancementRequest();enhanceReq.setImageBase64(imageBase64);enhanceReq.setEnhanceType(&quot;text_sharpen&quot;);  // 文字锐化ImageEnhancementResponse enhanceResp = client.ImageEnhancement(enhanceReq);String enhancedBase64 = enhanceResp.getImage();// 再用增强后的图片做 OCR

3. 指定识别语言
