req.setLanguageType(&quot;zh&quot;);  // 中文req.setLanguageType(&quot;en&quot;);  // 英文req.setLanguageType(&quot;zh_en&quot;); // 中英文混合

4. 身份证&#x2F;票据用专用接口
通用 OCR 不如专用接口准。如果是身份证、发票等，直接用专用接口：
// 身份证识别IDCardOCRRequest req = new IDCardOCRRequest();req.setImageBase64(imageBase64);IDCardOCRResponse resp = client.IDCardOCR(req);// 发票识别RecognizeGeneralInvoiceRequest req = new RecognizeGeneralInvoiceRequest();req.setImageBase64(imageBase64);RecognizeGeneralInvoiceResponse resp = client.RecognizeGeneralInvoice(req);

LLM 调优1. System Prompt 要写好
GPT 的 system prompt 对输出质量影响巨大。别光传 user 消息，加一个 system 消息效果翻倍：
messages.add(Map.of(&quot;role&quot;, &quot;system&quot;, &quot;content&quot;,     &quot;你是一个技术助手，回答要简洁，尽量用代码示例说明&quot;));

2. 控制 temperature
temperature 越低，回答越保守、稳定；越高，越有创意但也容易胡说八道。

问答类：temperature 0.3 - 0.5
创意类：temperature 0.7 - 0.9

requestBody.put(&quot;temperature&quot;, 0.5);

3. 处理 token 限制
GPT-3.5 单次最多 4096 token，超出就报错。如果对话太长，可以：

只保留最近几轮对话
用 max_tokens 限制回复长度

4. 请求失败加重试
网络波动经常导致请求失败，加个重试机制：
int retries = 3;while (retries &gt; 0) &#123;    try &#123;        // 调用 API        break;    &#125; catch (Exception e) &#123;        retries--;        if (retries == 0) throw e;        Thread.sleep(1000);    &#125;&#125;


五、OCR 结果的后续处理OCR 识别出来的文字，经常空格、换行乱七八糟，还带一堆没用的话。识别只是第一步，清洗和结构化才是重头戏。
下面是总结的几个处理套路。1. 先去掉乱七八糟的字符OCR 经常会识别出莫名其妙的符号，比如把一识别成—，把0识别成O。
public class OcrCleaner &#123;    public static String clean(String rawText) &#123;        if (rawText == null) return null;                // 1. 去掉所有空格和换行        String cleaned = rawText.replaceAll(&quot;\\s+&quot;, &quot;&quot;);                // 2. 常见 OCR 错别字纠正（这个靠经验慢慢积累）        cleaned = cleaned.replace(&quot;一&quot;, &quot;—&quot;)                 .replace(&quot;0&quot;, &quot;O&quot;)           // 数字0和字母O混淆                 .replace(&quot;1&quot;, &quot;I&quot;)           // 数字1和字母I混淆                 .replace(&quot;巳&quot;, &quot;已&quot;)          // 已和巳混淆                 .replace(&quot;未&quot;, &quot;末&quot;);         // 未和末混淆                // 3. 去掉重复标点        cleaned = cleaned.replaceAll(&quot;([。，！？；：])\\1+&quot;, &quot;$1&quot;);                return cleaned;    &#125;&#125;


2. 提取关键信息（正则）大部分业务场景关心的只是几个关键字段。用正则表达式直接捞出来。
示例1：提取身份证号public String extractIdCard(String rawText) &#123;    // 身份证号：18位，最后一位可能是X    Pattern pattern = Pattern.compile(&quot;[1-9]\\d&#123;16&#125;[0-9Xx]&quot;);    Matcher matcher = pattern.matcher(rawText);    if (matcher.find()) &#123;        return matcher.group().toUpperCase();    &#125;    return null;&#125;

示例2：提取手机号public String extractPhone(String rawText) &#123;    // 手机号：1开头的11位数字    Pattern pattern = Pattern.compile(&quot;1[3-9]\\d&#123;9&#125;&quot;);    Matcher matcher = pattern.matcher(rawText);    if (matcher.find()) &#123;        return matcher.group();    &#125;    return null;&#125;

示例3：提取金额public BigDecimal extractAmount(String rawText) &#123;    // 匹配 xx.xx 或 xx 格式的金额    Pattern pattern = Pattern.compile(&quot;(\\d+\\.?\\d&#123;0,2&#125;)&quot;);    Matcher matcher = pattern.matcher(rawText);    if (matcher.find()) &#123;        return new BigDecimal(matcher.group());    &#125;    return null;&#125;

示例4：提取姓名（这个比较难，姓名没有固定格式）可以用关键词定位：
public String extractName(String rawText) &#123;    // 寻找“姓名：”或“收件人：”后面的内容    Pattern pattern = Pattern.compile(&quot;(?:姓名|收件人|名称)[：:]\\s*([^\\s\\n]&#123;2,4&#125;)&quot;);    Matcher matcher = pattern.matcher(rawText);    if (matcher.find()) &#123;        return matcher.group(1);    &#125;    return null;&#125;


3. 结构化提取（用 LLM 兜底）正则表达式能搞定 80% 的情况，但遇到格式千奇百怪的文本可以用 LLM 来提取结构化信息。
@Service@Slf4jpublic class OcrStructureService &#123;        @Autowired    private LlmService llmService;        //用 LLM 把 OCR 结果转成结构化 JSON    public JSONObject extractWithLLM(String ocrText) &#123;        String prompt = String.format(            &quot;从以下文本中提取关键信息，返回 JSON 格式。\n&quot; +            &quot;需要提取：姓名、手机号、身份证号、地址。\n&quot; +            &quot;如果某个字段找不到，设为 null。\n\n&quot; +            &quot;文本内容：\n%s\n\n&quot; +            &quot;请只返回 JSON，不要有其他内容。&quot;,            ocrText        );                String result = llmService.chat(prompt);                // 解析返回的 JSON        try &#123;            return JSON.parseObject(result);        &#125; catch (Exception e) &#123;            log.error(&quot;LLM 解析失败: &#123;&#125;&quot;, e);            return new JSONObject();        &#125;    &#125;&#125;


正则能搞定的一律用正则，快且免费
正则搞不定的、格式特别乱的，再用 LLM 兜底
可以把两种方式组合，先正则，再让 LLM 补


六、总结折腾下来最大的感受是：调 API 不难，难的是把效果调好。每个服务官方给的 demo 都能跑通，但真要拿到实际场景用，就得各种调参数、加预处理。

Langchain4j 简易教程1.Langchain4j的介绍  主流的调用大模型的工具库有两种，一是 Langchain4j，二是SpringAI。简单来说Langchain4j是java调用大模型的工具库，使大模型和传统的软件深度融合。今天学习简单的 Langchain4j的应用。

2.快速入门——使用Spring整合 Langchain4j
创建SpringBoot项目
引入 Langchain4j起步依赖
在application.yml配置大模型信息，便于调用
编写controller层，调用大模型

  @RestControllerpublic class ChatController &#123;    @Autowired    private OpenAiChatModel model;     @RequestMapping(&quot;/chat&quot;)    public String chat(String message)&#123;        String result = model.chat(message);        return result;    &#125;&#125;


3.AIService 工具类  AIService工具类是用于调用大模型的，前面例子用于调用大模型的方式不太常用，因为比较麻烦。AIService整合了很多高级功能，比如会话记忆、RAG知识库等等，如果调用chat方法，这些工具都需要自己编写，比较麻烦。

AIService工具类使用方法
引入AIService依赖
声明封装聊天的接口   public interface ConsultantService &#123;//用于聊天的方法,message为用户输入的内容public String chat(String message);&#125;
创建动态代理对象 //config配置类@Configuration  public class CommonConfig &#123;  @Autowired  private OpenAiChatModel model;  @Bean           public ConsultantService consultantService() &#123;      ConsultantService cs = AiServices.builder(ConsultantService.class)              .chatModel(model)//设置对话时使用的模型对象              .build();      return cs;    &#125;  &#125;
